/**
 * Core event and data contract types for Worldcraft ecosystem
 * Shared across worldcraft, plotailor, narrative-nano
 */

// --- Event & Graph Contracts ---
export type DeltaOperation = 'create' | 'update' | 'delete' | 'patch';

export interface StateDeltaEvent<T = unknown> {
  id: string;
  timestamp: number;
  entityId: string;
  operation: DeltaOperation;
  path?: string[];
  previousValue?: T;
  newValue?: T;
  metadata?: Record<string, unknown>;
}

export interface GraphEdge<TEdge = unknown> {
  id: string;
  source: string;
  target: string;
  relation: string;
  data?: TEdge;
}

export interface SubgraphSlice<TNode = unknown, TEdge = unknown> {
  id: string;
  rootNodeId: string;
  depth: number;
  nodes: Record<string, TNode>;
  edges: GraphEdge<TEdge>[];
  version: number;
  metadata?: Record<string, unknown>;
}

export interface NarrativeContext {
  characterIds: string[];
  locationId?: string;
  timelinePoint?: number;
  activePlots: string[];
}

// --- Celestial & Calendar Contracts ---
export interface CustomDate {
  eraId?: string;
  year: number;
  month: number;
  day: number;
}

export interface CalendarDefinition {
  id: string;
  name: string;
  monthsPerYear: number;
  daysPerMonth: number[];
  leapMonth?: number;
  leapYearInterval?: number;
}

export interface SatelliteDefinition {
  id: string;
  name: string;
  synodicPeriodDays: number;
  phaseOffsetDays: number;
}

// --- Epistemic & Character Contracts ---
export interface CharacterState {
  id: string;
  name: string;
  aliases: string[];
  currentLocationId: string;
  isAlive: boolean;
  birthYear?: number;
  deathYear?: number;
}

export interface VerificationResult {
  status: 'VALID' | 'VIOLATION' | 'AMBIGUOUS';
  reason?: string;
  confidence: number;
}

// --- Lore & Linter Regulation Contracts ---
export interface TermRegulation {
  canonical: string;
  forbidden: string[];
  category: string;
}

// --- SPSC Ring Buffer Protocol Contracts ---
export const PACKET_SENTINEL_NORMAL = 0xAA;
export const PACKET_SENTINEL_WRAP = 0xFF;
export const FIXED_PACKET_SIZE = 320; // 64B Header + 256B Payload

export interface SharedMemoryHeader {
  writePointer: number;
  readPointer: number;
  droppedPackets: number;
  lastProcessedTimestamp: number;
}
